//! Discord Gateway/Webhook channel for IronClaw.//!//! This WASM component implements the channel interface for handling Discord//! interactions via webhooks and sending messages back to Discord.//!//! # Features//!//! - URL verification for Discord interactions//! - Slash command handling//! - Message event parsing (@mentions, DMs)//! - Thread support for conversations//! - Response posting via Discord Web API//! - Automatic message truncation (> 2000 chars)//!//! # Security//!//! - Signature validation is handled in-channel using Discord's Ed25519 headers//! - Bot token is injected by host during HTTP requests//! - WASM never sees raw credentialswit_bindgen::generate!({    world: "sandboxed-channel",    path: "../../wit/channel.wit",});use std::{cmp::Ordering, collections::HashMap};use ed25519_dalek::{Signature, Verifier, VerifyingKey};use serde::{Deserialize, Serialize};use exports::near::agent::channel::{    AgentResponse, ChannelConfig, Guest, HttpEndpointConfig, IncomingHttpRequest,    OutgoingHttpResponse, PollConfig, StatusUpdate,};use near::agent::channel_host::{self, EmittedMessage};/// Discord interaction wrapper.#[derive(Debug, Deserialize)]struct DiscordInteraction {    /// Interaction type (1=Ping, 2=ApplicationCommand, 3=MessageComponent)    #[serde(rename = "type")]    interaction_type: u8,    /// Interaction ID    id: String,    /// Application ID    application_id: String,    /// Guild ID (if in server)    #[allow(dead_code)] // Part of API payload, currently unused    guild_id: Option<String>,    /// Channel ID    channel_id: Option<String>,    /// Member info (if in server)    member: Option<DiscordMember>,    /// User info (if DM)    user: Option<DiscordUser>,    /// Command data (for slash commands)    data: Option<DiscordCommandData>,    /// Message (for component interactions)    message: Option<DiscordMessage>,    /// Token for responding    token: String,}#[derive(Debug, Deserialize, Clone)]struct DiscordMember {    user: DiscordUser,    #[allow(dead_code)] // Part of API payload, currently unused    nick: Option<String>,}#[derive(Debug, Deserialize, Clone)]struct DiscordUser {    id: String,    username: String,    global_name: Option<String>,}#[derive(Debug, Deserialize, Clone)]struct DiscordCommandData {    #[allow(dead_code)] // Part of API payload, currently unused    id: String,    name: String,    options: Option<Vec<DiscordCommandOption>>,}#[derive(Debug, Deserialize, Clone)]struct DiscordCommandOption {    name: String,    value: serde_json::Value,}#[derive(Debug, Deserialize, Clone)]struct DiscordMessage {    #[allow(dead_code)] // Part of API payload, currently unused    id: String,    content: String,    channel_id: String,    #[allow(dead_code)] // Part of API payload, currently unused    author: DiscordUser,}#[derive(Debug, Deserialize)]struct DiscordChannelMessage {    id: String,    content: String,    channel_id: String,    author: DiscordChannelAuthor,    #[serde(default)]    mentions: Vec<DiscordUser>,    #[serde(default)]    webhook_id: Option<String>,}#[derive(Debug, Deserialize)]struct DiscordChannelAuthor {    id: String,    username: String,    global_name: Option<String>,    #[serde(default)]    bot: bool,}#[derive(Debug, Clone, Serialize, Deserialize)]struct DiscordRuntimeConfig {    #[serde(default = "default_require_signature_verification")]    require_signature_verification: bool,    #[serde(default)]    webhook_secret: Option<String>,    #[serde(default)]    polling_enabled: bool,    #[serde(default = "default_poll_interval_ms")]    poll_interval_ms: u32,    #[serde(default)]    mention_channel_ids: Vec<String>,    #[serde(default)]    owner_id: Option<String>,    #[serde(default = "default_dm_policy")]    dm_policy: String,    #[serde(default)]    allow_from: Vec<String>,}fn default_poll_interval_ms() -> u32 {    30_000}fn default_require_signature_verification() -> bool {    true}fn default_dm_policy() -> String {    "pairing".to_string()}fn default_runtime_config() -> DiscordRuntimeConfig {    DiscordRuntimeConfig {        require_signature_verification: default_require_signature_verification(),        webhook_secret: None,        polling_enabled: false,        poll_interval_ms: default_poll_interval_ms(),        mention_channel_ids: Vec::new(),        owner_id: None,        dm_policy: default_dm_policy(),        allow_from: Vec::new(),    }}/// Workspace path for persisting owner_id across WASM callbacks.const OWNER_ID_PATH: &str = "state/owner_id";/// Workspace path for persisting dm_policy across WASM callbacks.const DM_POLICY_PATH: &str = "state/dm_policy";/// Workspace path for persisting allow_from (JSON array) across WASM callbacks.const ALLOW_FROM_PATH: &str = "state/allow_from";/// Channel name for pairing store (used by pairing host APIs).const CHANNEL_NAME: &str = "discord";/// Metadata stored with emitted messages for response routing.#[derive(Debug, Serialize, Deserialize)]struct DiscordMessageMetadata {    /// Discord channel ID    channel_id: String,    /// Interaction ID for followups    #[serde(default)]    interaction_id: Option<String>,    /// Interaction token for responding    #[serde(default)]    token: Option<String>,    /// Application ID    #[serde(default)]    application_id: Option<String>,    /// Source message ID when handling mention-poll events.    #[serde(default)]    source_message_id: Option<String>,    /// Thread ID (for forum threads)    thread_id: Option<String>,}struct DiscordChannel;impl Guest for DiscordChannel {    fn on_start(config_json: String) -> Result<ChannelConfig, String> {        channel_host::log(channel_host::LogLevel::Info, "Discord channel starting");        let config =            serde_json::from_str::<DiscordRuntimeConfig>(&config_json).unwrap_or_else(|e| {                channel_host::log(                    channel_host::LogLevel::Warn,                    &format!("Invalid config JSON, using defaults: {}", e),                );                default_runtime_config()            });        if let Ok(serialized) = serde_json::to_string(&config) {            let _ = channel_host::workspace_write("config.json", &serialized);        }        if config.require_signature_verification            && config                .webhook_secret                .as_deref()                .map(str::trim)                .filter(|s| !s.is_empty())                .is_none()        {            channel_host::log(                channel_host::LogLevel::Error,                "Discord channel misconfigured: require_signature_verification=true but webhook_secret is empty",            );        } else if !config.require_signature_verification {            channel_host::log(                channel_host::LogLevel::Warn,                "Discord signature verification is disabled; webhook endpoint is unprotected",            );        }        // Persist owner_id so subsequent callbacks can read it.        if let Some(ref owner_id) = config.owner_id {            let _ = channel_host::workspace_write(OWNER_ID_PATH, owner_id);            channel_host::log(                channel_host::LogLevel::Info,                &format!("Owner restriction enabled: user {}", owner_id),            );        } else {            let _ = channel_host::workspace_write(OWNER_ID_PATH, "");        }        // Persist dm_policy and allow_from for DM pairing.        let _ = channel_host::workspace_write(DM_POLICY_PATH, &config.dm_policy);        let allow_from_json =            serde_json::to_string(&config.allow_from).unwrap_or_else(|_| "[]".to_string());        let _ = channel_host::workspace_write(ALLOW_FROM_PATH, &allow_from_json);        Ok(ChannelConfig {            display_name: "Discord".to_string(),            http_endpoints: vec![HttpEndpointConfig {                path: "/webhook/discord".to_string(),                methods: vec!["POST".to_string()],                require_secret: false,            }],            poll: if config.polling_enabled {                Some(PollConfig {                    interval_ms: config.poll_interval_ms.max(30_000),                    enabled: true,                })            } else {                None            },        })    }    fn on_http_request(req: IncomingHttpRequest) -> OutgoingHttpResponse {        let config = load_runtime_config();        let headers: HashMap<String, String> =            serde_json::from_str(&req.headers_json).unwrap_or_default();        if config.require_signature_verification {            if config                .webhook_secret                .as_deref()                .map(str::trim)                .filter(|s| !s.is_empty())                .is_none()            {                channel_host::log(                    channel_host::LogLevel::Error,                    "Discord channel misconfigured: webhook_secret not set while verification is required",                );                return json_response(                    500,                    serde_json::json!({"error": "Channel misconfigured: webhook_secret not set"}),                );            }            if !verify_discord_request_signature(                headers,                &req.body,                config.webhook_secret.as_deref(),            ) {                channel_host::log(                    channel_host::LogLevel::Warn,                    "Discord signature verification failed",                );                return json_response(401, serde_json::json!({"error": "Invalid signature"}));            }        } else {            channel_host::log(                channel_host::LogLevel::Warn,                "Discord signature verification is disabled; accepting unverified webhook request",            );        }        let body_str = match std::str::from_utf8(&req.body) {            Ok(s) => s,            Err(_) => {                return json_response(400, serde_json::json!({"error": "Invalid UTF-8 body"}));            }        };        let interaction: DiscordInteraction = match serde_json::from_str(body_str) {            Ok(i) => i,            Err(e) => {                channel_host::log(                    channel_host::LogLevel::Error,                    &format!("Failed to parse Discord interaction: {}", e),                );                return json_response(400, serde_json::json!({"error": "Invalid interaction"}));            }        };        match interaction.interaction_type {            // Ping - Discord verification            1 => {                channel_host::log(channel_host::LogLevel::Info, "Responding to Discord ping");                json_response(200, serde_json::json!({"type": 1}))            }            // Application Command (slash command)            2 => {                if handle_slash_command(&interaction) {                    json_response(                        200,                        serde_json::json!({                            "type": 5,                            "data": {                                "content": "🤔 Thinking..."                            }                        }),                    )                } else {                    json_response(                        200,                        serde_json::json!({                            "type": 4,                            "data": {                                "content": "You are not authorized to use this bot.",                                "flags": 64                            }                        }),                    )                }            }            // Message Component (buttons, selects)            3 => {                if let Some(ref message) = interaction.message {                    handle_message_component(&interaction, message);                }                json_response(200, serde_json::json!({"type": 6}))            }            _ => {                channel_host::log(                    channel_host::LogLevel::Warn,                    &format!(                        "Unknown Discord interaction type: {}",                        interaction.interaction_type                    ),                );                json_response(200, serde_json::json!({"type": 6}))            }        }    }    fn on_poll() {        poll_for_mentions();    }    fn on_respond(response: AgentResponse) -> Result<(), String> {        let metadata: DiscordMessageMetadata = serde_json::from_str(&response.metadata_json)            .map_err(|e| format!("Failed to parse metadata: {}", e))?;        // Truncate content to 2000 characters to comply with Discord limits        let content = truncate_message(&response.content);        let mut payload = serde_json::json!({ "content": content });        // Check for embeds in metadata        if let Ok(meta_json) = serde_json::from_str::<serde_json::Value>(&response.metadata_json) {            if let Some(embeds) = meta_json.get("embeds") {                payload["embeds"] = embeds.clone();            }        }        let payload_bytes =            serde_json::to_vec(&payload).map_err(|e| format!("Failed to serialize: {}", e))?;        let headers = serde_json::json!({            "Content-Type": "application/json"        });        let (method, url) = if let (Some(application_id), Some(token)) =            (metadata.application_id.as_ref(), metadata.token.as_ref())        {            (                "PATCH",                format!(                    "https://discord.com/api/v10/webhooks/{}/{}/messages/@original",                    application_id, token                ),            )        } else if let Some(source_message_id) = metadata.source_message_id.as_ref() {            payload["message_reference"] = serde_json::json!({                "message_id": source_message_id            });            payload["allowed_mentions"] = serde_json::json!({                "replied_user": true            });            let mention_payload = serde_json::to_vec(&payload)                .map_err(|e| format!("Failed to serialize mention payload: {}", e))?;            let mention_url = format!(                "https://discord.com/api/v10/channels/{}/messages",                metadata.channel_id            );            let result = channel_host::http_request(                "POST",                &mention_url,                &discord_auth_headers_json(true),                Some(&mention_payload),                None,            );            return map_discord_response(result);        } else {            return Err("Unsupported Discord response metadata".to_string());        };        let result = channel_host::http_request(            method,            &url,            &headers.to_string(),            Some(&payload_bytes),            None,        );        map_discord_response(result)    }    fn on_status(_update: StatusUpdate) {}    fn on_broadcast(_user_id: String, _response: AgentResponse) -> Result<(), String> {        Err("broadcast not yet implemented for Discord channel".to_string())    }    fn on_shutdown() {        channel_host::log(            channel_host::LogLevel::Info,            "Discord channel shutting down",        );    }}